INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES (1, "自身や知り合いと全く同じ姿をした\n人物に出会う…そんな噂だ。", 0, 11, 0, 10, 19220021, 0, 115711, 922, 0.5);
