INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES (1, "フードコートで売っているのであれば\n何ら違和感はないけれど。", 0, 11, 0, 10, 19230021, 0, 115711, 923, 0.5);
